def integer_cuberoot(n: int) -> int:
    lo, hi = 0, 1_000_001
    while lo + 1 < hi:
        mid = (lo + hi) // 2
        if mid * mid * mid <= n:
            lo = mid
        else:
            hi = mid
    return lo


def solve() -> None:
    n = int(sys.stdin.readline())
    limit = integer_cuberoot(n)

    for d in range(1, limit + 1):
        if n % d != 0:
            continue

        q = n // d
        disc = 12 * q - 3 * d * d
        if disc < 0:
            continue

        root = math.isqrt(disc)
        if root * root != disc:
            continue

        numerator = root - 3 * d
        if numerator <= 0 or numerator % 6 != 0:
            continue

        y = numerator // 6
        x = y + d

        if x * x * x - y * y * y == n:
            print(x, y)
            return

    print(-1)


