        pw = [1] * (D + 1)
        for h in range(1, D + 1):
            pw[h] = pw[h - 1] * p % MOD

        # dp0[h]: weighted walks currently at h that have not visited height 0.
        # dp1[h]: weighted walks currently at h that have visited height 0.
        dp0 = [0] * (D + 1)
        dp1 = [0] * (D + 1)

        dp1[0] = 1
        for h in range(1, D + 1):
            dp0[h] = pw[h]

