            ndp0 = [0] * (D + 1)
            ndp1 = [0] * (D + 1)

            if a == 0:
                for h in range(D + 1):
                    w = pw[h]
                    if dp0[h]:
                        ndp0[h] = dp0[h] * w % MOD
                    if dp1[h]:
                        ndp1[h] = dp1[h] * w % MOD
            else:
                for h in range(D + 1):
                    v0 = dp0[h]
                    v1 = dp1[h]
                    if v0 == 0 and v1 == 0:
                        continue

                    t = h - a
                    if t >= 0:
                        w = pw[t]
                        if t == 0:
                            ndp1[t] = (ndp1[t] + (v0 + v1) * w) % MOD
                        else:
                            if v0:
                                ndp0[t] = (ndp0[t] + v0 * w) % MOD
                            if v1:
                                ndp1[t] = (ndp1[t] + v1 * w) % MOD

                    t = h + a
                    if t <= D:
                        w = pw[t]
                        if t == 0:
                            ndp1[t] = (ndp1[t] + (v0 + v1) * w) % MOD
                        else:
