import sys

def solve():
    input = sys.stdin.readline
    N, p = map(int, input().split())
    A = [list(map(int, input().split())) for _ in range(N)]

    if p == 2:
        x = N & 1
        line = " ".join([str(x)] * N)
        print("\n".join([line] * N))
        return

    zeros = []
    K = 0
    for i in range(N):
        for j in range(N):
            if A[i][j] == 0:
                zeros.append((i, j))
                K += 1

    C = A

    def matmul(X, Y):
        Z = [[0] * N for _ in range(N)]
        for i in range(N):
            zi = Z[i]
            xi = X[i]
            for k, x in enumerate(xi):
                if x:
                    yk = Y[k]
                    for j in range(N):
                        zi[j] += x * yk[j]
            for j in range(N):
                zi[j] %= p
        return Z

    def matpow(X, e):
        R = [[0] * N for _ in range(N)]
        for i in range(N):
            R[i][i] = 1
        while e:
            if e & 1:
                R = matmul(R, X)
            X = matmul(X, X)
            e >>= 1
        return R

    if p == 3:
        answer = matmul(matmul(C, C), C)

        # For every zero edge E_(u,v), add ECE.
        # If it is a loop, also add CE^2 + E^2C = CE + EC.
        for u, v in zeros:
            answer[u][v] = (answer[u][v] + C[v][u]) % p
            if u == v:
                for r in range(N):
                    answer[r][u] = (answer[r][u] + C[r][u]) % p
                for c in range(N):
                    answer[u][c] = (answer[u][c] + C[u][c]) % p
    else:
        answer = matpow(C, p)

        # Only zero loops can occur p-1 times in a length-p walk.
        # Their total extra contribution is CE + EC - 2*CEE.
        for i in range(N):
            if C[i][i] == 0:
                for r in range(N):
                    answer[r][i] = (answer[r][i] + C[r][i]) % p
                for c in range(N):
                    answer[i][c] = (answer[i][c] + C[i][c]) % p
                answer[i][i] = (answer[i][i] - 2 * C[i][i]) % p

    if K & 1:
        for i in range(N):
            for j in range(N):
                answer[i][j] = (-answer[i][j]) % p

    for row in answer:
        print(*row)

if __name__ == "__main__":
    solve()

from typing import List
from bisect import bisect_right


class Solution:
    def maximumWeight(self, intervals: List[List[int]]) -> List[int]:
        n = len(intervals)

        # Store (start, end, weight, original_index), ordered by start.
        arr = sorted(
            (left, right, weight, i)
            for i, (left, right, weight) in enumerate(intervals)
        )
        starts = [item[0] for item in arr]

        # nxt[i]: first interval starting strictly after arr[i]'s end.
        # bisect_right is necessary because touching endpoints overlap.
        nxt = [0] * n
        for i in range(n):
            nxt[i] = bisect_right(starts, arr[i][1])

        # dp[i][k] = (best total score, sorted tuple of original indices)
        # using at most k intervals from arr[i:].
        dp = [[(0, ()) for _ in range(5)] for _ in range(n + 1)]

        for i in range(n - 1, -1, -1):
            _, _, weight, original_index = arr[i]

            for k in range(5):
                best = dp[i + 1][k]  # Do not take interval i.

                if k:
                    suffix_score, suffix_indices = dp[nxt[i]][k - 1]
                    candidate = (
                        suffix_score + weight,
                        tuple(sorted(suffix_indices + (original_index,))),
                    )

                    if (
                        candidate[0] > best[0]
                        or (
                            candidate[0] == best[0]
                            and candidate[1] < best[1]
                        )
                    ):
                        best = candidate

                dp[i][k] = best

        return list(dp[0][4][1])

from typing import List, Optional, Tuple


class Solution:
    def maxSubarraySum(self, nums: List[int]) -> int:
        # Each summary is:
        # (total_sum, maximum_prefix_sum, maximum_suffix_sum, maximum_subarray_sum)
        Summary = Tuple[int, int, int, int]

        def merge(a: Optional[Summary], b: Optional[Summary]) -> Optional[Summary]:
            if a is None:
                return b
            if b is None:
                return a

            total_a, pref_a, suff_a, best_a = a
            total_b, pref_b, suff_b, best_b = b

            total = total_a + total_b
            pref = max(pref_a, total_a + pref_b)
            suff = max(suff_b, total_b + suff_a)
            best = max(best_a, best_b, suff_a + pref_b)
            return total, pref, suff, best

        n = len(nums)
        size = 1
        while size < n:
            size <<= 1

        tree: List[Optional[Summary]] = [None] * (2 * size)

        for i, value in enumerate(nums):
            tree[size + i] = (value, value, value, value)

        for i in range(size - 1, 0, -1):
            tree[i] = merge(tree[i << 1], tree[i << 1 | 1])

        def query(left: int, right: int) -> Optional[Summary]:
            """Return summary for nums[left:right], preserving element order."""
            left += size
            right += size
            result_left: Optional[Summary] = None
            result_right: Optional[Summary] = None

            while left < right:
                if left & 1:
                    result_left = merge(result_left, tree[left])
                    left += 1
                if right & 1:
                    right -= 1
                    result_right = merge(tree[right], result_right)
                left >>= 1
                right >>= 1

            return merge(result_left, result_right)

        answer = tree[1][3]

        positions = {}
        for i, value in enumerate(nums):
            if value < 0:
                positions.setdefault(value, []).append(i)

        for occurrences in positions.values():
            combined: Optional[Summary] = None
            previous = 0

            for index in occurrences:
                if previous < index:
                    combined = merge(combined, query(previous, index))
                previous = index + 1

            if previous < n:
                combined = merge(combined, query(previous, n))

            if combined is not None:
                answer = max(answer, combined[3])

        return answer

class Solution:
    def minLength(self, s: str, numOps: int) -> int:
        n = len(s)

        def feasible(max_run: int) -> bool:
            if max_run == 1:
                flips_start_zero = 0
                flips_start_one = 0

                for i, ch in enumerate(s):
                    if ch != ('0' if i % 2 == 0 else '1'):
                        flips_start_zero += 1
                    if ch != ('1' if i % 2 == 0 else '0'):
                        flips_start_one += 1

                return min(flips_start_zero, flips_start_one) <= numOps

            needed = 0
            run_length = 1

            for i in range(1, n):
                if s[i] == s[i - 1]:
                    run_length += 1
                else:
                    needed += run_length // (max_run + 1)
                    if needed > numOps:
                        return False
                    run_length = 1

            needed += run_length // (max_run + 1)
            return needed <= numOps

        left, right = 1, n

        while left < right:
            mid = (left + right) // 2
            if feasible(mid):
                right = mid
            else:
                left = mid + 1

        return left

from typing import List


class Solution:
    def countComponents(self, nums: List[int], threshold: int) -> int:
        present = []
        isolated = 0

        for x in nums:
            if x > threshold:
                isolated += 1
            else:
                present.append(x)

        parent = list(range(threshold + 1))
        size = [1] * (threshold + 1)

        def find(x: int) -> int:
            while parent[x] != x:
                parent[x] = parent[parent[x]]
                x = parent[x]
            return x

        def union(a: int, b: int) -> None:
            ra = find(a)
            rb = find(b)
            if ra == rb:
                return
            if size[ra] < size[rb]:
                ra, rb = rb, ra
            parent[rb] = ra
            size[ra] += size[rb]

        # representative[m] is one present input value dividing m.
        # All present divisors of the same m are pairwise connected,
        # because their LCM divides m <= threshold.
        representative = [0] * (threshold + 1)

        for d in present:
            for m in range(d, threshold + 1, d):
                if representative[m] == 0:
                    representative[m] = d
                else:
                    union(d, representative[m])

        roots = set()
        for x in present:
            roots.add(find(x))

        return isolated + len(roots)
